/**
 * Structurizr DSL grammar inventory.
 *
 * Source: https://docs.structurizr.com/dsl/language plus the Basics, Archetypes,
 * Expressions and Includes pages (fetched 2026-10-29; docs site binaries v2026.09.19).
 *
 * This is DATA, not parser code. It is the single source of truth for:
 *   - the per-context keyword tables the parser will use,
 *   - the human-readable docs/grammar-inventory.md (generated by scripts/gen-inventory.ts),
 *   - spec-coverage tests.
 *
 * Statements are matched case-insensitively (the spec says keywords are
 * case-insensitive); `keyword` holds the canonical spelling.
 */

export type Status =
  | "planned" //     in scope for the first parser iteration
  | "deferred" //    parsed into a node, never executed; emits a "not supported" diagnostic
  | "deprecated" //  parsed, emits a deprecation warning
  | "unverified"; // present in the spec but under-documented, or recalled from older docs; verify against fixtures

export interface Statement {
  /** Canonical spelling. For operators this is a label such as "->". */
  keyword: string;
  /** Syntax as in the spec: <required> [optional]. */
  syntax: string;
  /** "keyword" is led by a keyword; "operator" is recognised by a relationship-arrow token. */
  kind?: "keyword" | "operator";
  /** Whether a `{ }` body may / must follow. Default "none". */
  block?: "none" | "optional" | "required";
  /** Context entered by the body, if any. */
  opens?: string;
  /** Can be prefixed with `identifier =`. */
  assignable?: boolean;
  /** The body is raw text in another language (inline scripts), not DSL. */
  rawBody?: boolean;
  status?: Status;
  note?: string;
}

export interface Context {
  id: string;
  title: string;
  /** How this context is entered, for humans. */
  entered: string;
  statements: Statement[];
  /** Grammar of body lines when the body is not (only) keyword-led. */
  lines?: string;
  /**
   * How non-keyword lines are parsed:
   *  pair        `<name> <value>` style lines (arity from lineArity)
   *  identifiers a list of identifiers per line
   *  archetype   `<name> = <base> [{ }]` archetype definitions
   *  dynamic     `[order:] a -> b ...` and `[order:] relationshipId ...` lines
   */
  lineKind?: "pair" | "identifiers" | "archetype" | "dynamic";
  /** Allowed token count per line for pair/identifiers lines: [min, max] (null = unbounded). */
  lineArity?: [number, number | null];
  /** Body is raw text, not DSL (inline scripts). */
  raw?: boolean;
  /** Base kinds whose user-defined archetypes act as extra keywords in this context. */
  archetypeKinds?: string[];
  note?: string;
}

// ---------------------------------------------------------------------------
// Small builders
// ---------------------------------------------------------------------------

const s = (keyword: string, syntax: string, o: Partial<Statement> = {}): Statement => ({ keyword, syntax, ...o });

const DESC = s("description", "description <text>");
const TECH = s("technology", "technology <text>");
const URL_ = s("url", "url <url>");
const TAG = s("tag", "tag <tag>");
const TAGS = s("tags", "tags <tag> [tag...]", { note: "Comma separated, or individual arguments, or both." });
const PROPS = s("properties", "properties { <name> <value> ... }", { block: "required", opens: "properties" });
const PERSP = s("perspectives", "perspectives { ... }", { block: "required", opens: "perspectives" });
const DOCS = s("!docs", "!docs <path> [fqcn]");
const ADRS = s("!adrs", "!adrs <path> [type|fqn]");
const DECISIONS = s("!decisions", "!decisions <path> [type|fqn]", {
  status: "unverified",
  note: "Alias of !adrs; only seen in the 'portable DSL' list in the language reference.",
});
const REL = s(
  "->",
  "<source> -> <destination> [description] [technology] [tags]   |   -> <destination> [description] [technology] [tags]",
  {
    kind: "operator",
    block: "optional",
    opens: "relationshipBlock",
    assignable: true,
    note: "Second form: source is the element in scope. `this` refers to the element in scope.",
  },
);
const REL_ARCH = s(
  "--<archetype>->",
  "<source> --<archetype>-> <destination> [description] [technology] [tags]",
  { kind: "operator", block: "optional", opens: "relationshipBlock", assignable: true, note: "Relationship archetype; see `archetypes`." },
);
const ELEMENT_COMMON = [DESC, TAGS, TAG, URL_, PROPS, PERSP];
const IDENTIFIERS = s("!identifiers", "!identifiers <hierarchical|flat>");

// ---------------------------------------------------------------------------
// Enumerations the parser/resolver will validate against
// ---------------------------------------------------------------------------

export const ENUMS = {
  shape: [
    "Box", "RoundedBox", "Circle", "Ellipse", "Hexagon", "Diamond", "Cylinder", "Bucket", "Pipe", "Person",
    "Robot", "Folder", "WebBrowser", "Window", "Terminal", "Shell", "MobileDevicePortrait",
    "MobileDeviceLandscape", "Component",
  ],
  border: ["solid", "dashed", "dotted"],
  lineStyle: ["solid", "dashed", "dotted"],
  routing: ["Direct", "Orthogonal", "Curved"],
  autoLayoutDirection: ["tb", "bt", "lr", "rl"],
  identifiers: ["hierarchical", "flat"],
  scope: ["landscape", "softwaresystem", "none"],
  visibility: ["private", "public"],
  userRole: ["read", "write"],
  terminologyMetadata: ["square", "round", "curly", "angle", "double-angle", "none"],
  filteredMode: ["include", "exclude"],
  elementExpressionType: [
    "Person", "SoftwareSystem", "Container", "Component", "DeploymentNode", "InfrastructureNode",
    "SoftwareSystemInstance", "ContainerInstance", "Custom",
  ],
  archetypeBaseKinds: [
    "person", "softwareSystem", "container", "component", "deploymentNode", "infrastructureNode", "group", "element",
  ],
} as const;

// ---------------------------------------------------------------------------
// Directives valid wherever a statement may start (handled by the preprocessor)
// ---------------------------------------------------------------------------

export const GLOBAL_DIRECTIVES: Statement[] = [
  s("!include", "!include <file|directory|url>", {
    note: "Textual inlining at the point of use. A relative path inside the including file's directory or below; a directory includes its .dsl files; a URL must be HTTPS and needs a host that allows it.",
  }),
  s("!const", "!const <name> <value>", {
    note: "Defines a constant for `${name}` substitution in the lines that follow. Names use a-z A-Z 0-9 - _ . Constants cannot be redefined. Shown at file top level; whether it is legal in every context is not stated, so it is accepted anywhere.",
  }),
  s("!var", "!var <name> <value>", { note: "Like !const but may be redefined later." }),
  s("!script", "!script <groovy|kotlin|ruby|javascript> { ...raw code... }   |   !script <file>", {
    status: "deferred",
    block: "optional",
    rawBody: true,
    note: "Inline body is raw code, not DSL. Must be skipped without tokenizing.",
  }),
  s("!plugin", "!plugin <fqcn>", { status: "deferred", block: "optional", rawBody: true, note: "Parameter syntax is not in the language reference." }),
];

