// ---------------------------------------------------------------------------
// Findings that shape the design (each came directly from the spec pages)
// ---------------------------------------------------------------------------

export interface Finding {
  id: string;
  title: string;
  detail: string;
  impact: string;
}

export const FINDINGS: Finding[] = [
  {
    id: "F1",
    title: "Keywords are case-insensitive",
    detail: "`softwareSystem` and `softwaresystem` are equivalent (Basics).",
    impact: "Keyword tables are keyed by lower-cased text. Whether identifiers are also case-insensitive is not stated on the pages fetched (open question).",
  },
  {
    id: "F2",
    title: "Strictly line-oriented, with brace placement rules",
    detail: "`{` must be the last token of its statement's line; `}` must be alone on its line; braces only appear when there is child content.",
    impact: "The parser consumes `newline` tokens as statement terminators and can report brace-placement errors precisely.",
  },
  {
    id: "F3",
    title: "Imperative, in-order processing; no forward references",
    detail: "Lines are processed in order (Basics). An identifier must be defined before use.",
    impact: "The resolver can be single pass, and a use-before-define is a real error rather than something to defer.",
  },
  {
    id: "F4",
    title: "String substitution runs on token text, sequentially",
    detail: "`${NAME}` is replaced inside any token, including inside quoted strings. NAME can be a `!const`, a `!var` (redefinable later) or an environment variable; unknown names are left as-is.",
    impact: "A sequential preprocessor stage sits between tokenizer and parser. Environment variables must be injected through an option, because the core cannot touch process.env.",
  },
  {
    id: "F5",
    title: "!include is textual inlining",
    detail: "Content is inlined where the directive appears. Target is a file, a directory (all DSL files in it) or an HTTPS URL; local paths are relative to the parent file and must stay in its directory or below.",
    impact: "Handled in the preprocessor by splicing tokens, with each token keeping its origin file and range for diagnostics. The resolver interface needs readFile, listDirectory and (optionally) fetchUrl. A brace opened in one file may close in another.",
  },
  {
    id: "F6",
    title: "Relationship operators are tokens; expressions are words",
    detail: "`->`, `--archetype->` and `-/>` are operators. Expression words such as `->x`, `x->`, `->x->`, `*->*` are single arguments.",
    impact: "The tokenizer classifies exactly those three shapes as `arrow` and leaves everything else a `word` (implemented in this step).",
  },
  {
    id: "F7",
    title: "One keyword, many meanings",
    detail: "`container`, `component`, `element`, `relationship`, `group`, `description`, `metadata`, `image`, `properties` and `default` all mean different things in different contexts.",
    impact: "Keyword tables are per context (this inventory), never global.",
  },
  {
    id: "F8",
    title: "Archetypes add user-defined keywords",
    detail: "`application = container {...}` makes `application` usable wherever `container` is. Relationship archetypes make `--https->` valid.",
    impact: "In element-defining contexts, an unknown leading word is looked up in the archetype table built so far (valid, since processing is in order). Inventory field `archetypeKinds` says which base kinds apply where.",
  },
  {
    id: "F9",
    title: "Positional arguments with `\"\"` placeholders and optional quotes",
    detail: "Arguments are positional; `\"\"` skips an optional argument; quotes are optional when a value has no whitespace.",
    impact: "The syntax tree stores arguments positionally and distinguishes a skipped argument (empty string) from an absent one.",
  },
  {
    id: "F10",
    title: "Expressions are a sub-language",
    detail: "`element.tag==X`, `element.parent==id`, `&&`, `||`, `->id->`, `relationship.source==id` and so on; whitespace requires quoting the whole expression.",
    impact: "Kept as opaque strings in the syntax tree and parsed by a separate small expression parser in the resolver.",
  },
  {
    id: "F11",
    title: "!script bodies are raw code",
    detail: "`!script groovy { ... }` contains code in another language.",
    impact: "Even though execution is deferred, the body must be captured as raw text and skipped. Normal tokenizing would report spurious errors on quotes and comments inside it. The end-of-body rule is not documented (probably a lone `}` line); needs a fixture.",
  },
  {
    id: "F12",
    title: "!element body depends on its target",
    detail: "Children allowed in `!element <id> { }` are those of the referenced element's kind.",
    impact: "The parser accepts the union of element-body statements; the resolver validates once it knows the target kind.",
  },
  {
    id: "F13",
    title: "`group` is both a block and a property",
    detail: "`group <name> { }` is a block inside model/softwareSystem/container; `group <name>` inside a component is a property.",
    impact: "Distinguished by context, and by whether a `{` follows.",
  },
  {
    id: "F14",
    title: "Dynamic view bodies are not keyword-led",
    detail: "Lines are `[order:] a -> b [desc] [tech]` or `[order:] relId [desc]`.",
    impact: "The dynamic view context has its own line grammar alongside its keyword statements.",
  },
  {
    id: "F15",
    title: "Deprecated and Java-bound features still need nodes",
    detail: "`!ref` / `!extend` are deprecated. `!docs`, `!adrs`, `!components`, `!impliedRelationships <fqcn>`, `!script`, `!plugin` depend on files or the JVM.",
    impact: "All parse into nodes (so files load and outlines work). Deprecated ones carry a warning; JVM-bound ones carry a 'not supported' diagnostic.",
  },
  {
    id: "F16",
    title: "workspace extends can point at JSON",
    detail: "`workspace extends <file|url>` accepts a DSL or a JSON workspace; all identifiers of a DSL base are available.",
    impact: "Loading JSON workspaces is a second input format. It needs a decision on scope for the first iteration.",
  },
];

